/* Exercise library. Text: written for this app. Videos: YouTube embeds. Photos: Free Exercise DB (public domain, github.com/yuhonas/free-exercise-db). */
window.GYM_LIB=[{"id":"Barbell_Squat","name":"Приседания со штангой","group":"Ноги","muscles":"Квадрицепсы, ягодицы, приводящие, разгибатели спины","equip":"Штанга","level":"новичок","sets":3,"lo":6,"hi":10,"step":5,"unit":"кг","how":["Положи гриф на верх трапеций, сведи лопатки и крепко возьмись за штангу.","Сними штангу со стоек, отойди на пару шагов, стопы на ширине плеч, носки чуть врозь.","Вдохни, напряги пресс и опускайся, одновременно отводя таз назад и сгибая колени.","Колени веди по линии носков, опускайся до параллели бёдер с полом или чуть ниже.","Вставай, давя всей стопой в пол и сохраняя спину ровной."],"mistakes":["Колени заваливаются внутрь при подъёме.","Пятки отрываются от пола, вес уходит на носки.","Поясница округляется в нижней точке."],"tip":"Приседай в раме со страховочными упорами и перед каждым повтором вдыхай и напрягай пресс.","yt":"-c7BysX0c80","ych":"Кузница Спорта"},{"id":"Front_Barbell_Squat","name":"Фронтальные приседания","group":"Ноги","muscles":"Квадрицепсы, ягодицы, разгибатели спины, пресс","equip":"Штанга","level":"опытный","sets":3,"lo":6,"hi":10,"step":5,"unit":"кг","how":["Положи гриф на передние дельты у шеи и подними локти вперёд до уровня плеч.","Держи гриф пальцами хватом чуть шире плеч или скрести руки поверх грифа.","Отойди от стоек, поставь стопы на ширине плеч, носки чуть врозь, напряги пресс.","Опускайся вертикально вниз, сохраняя корпус прямым, а локти высоко.","Вставай, давя серединой стопы в пол и не давая локтям опускаться."],"mistakes":["Локти падают вниз, и штанга скатывается с плеч.","Корпус наклоняется вперёд, нагрузка уходит в поясницу.","Пятки отрываются от пола в нижней точке."],"tip":"Думай о том, чтобы толкать локти вверх, тогда корпус останется вертикальным.","yt":"FhAOGpl4ZT8","ych":"Кузница Спорта"},{"id":"Goblet_Squat","name":"Гоблет-присед с гантелью","group":"Ноги","muscles":"Квадрицепсы, ягодицы, приводящие, пресс","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Возьми гантель вертикально за верхний диск и прижми её к груди.","Поставь стопы чуть шире плеч, носки немного разверни наружу.","Опускайся между коленями, держа грудь поднятой и спину прямой.","Внизу локти окажутся внутри коленей, слегка разведи ими колени в стороны.","Поднимайся, давя всей стопой в пол и не отпуская гантель от груди."],"mistakes":["Гантель отходит от груди, и корпус заваливается вперёд.","Колени сводятся внутрь при подъёме.","Спина округляется в нижней точке."],"tip":"Держи гантель плотно у груди, она помогает сохранять корпус вертикальным.","yt":"1hf0d1b_0z0","ych":"Спортивные советы"},{"id":"Leg_Press","name":"Жим ногами","group":"Ноги","muscles":"Квадрицепсы, ягодицы, приводящие","equip":"Тренажёр","level":"новичок","sets":3,"lo":10,"hi":15,"step":5,"unit":"кг","how":["Сядь в тренажёр и плотно прижми поясницу и таз к спинке.","Поставь стопы на середину платформы на ширине плеч, носки чуть врозь.","Выжми платформу, сними её с упоров и опускай, сгибая колени примерно до прямого угла.","Выжимай платформу всей стопой, не выпрямляя колени до замка наверху.","После подхода обязательно верни упоры на место."],"mistakes":["Таз отрывается от сиденья в нижней точке.","Колени полностью выпрямляются и блокируются наверху.","Колени сводятся внутрь во время жима."],"tip":"Опускай платформу только до той точки, где таз ещё прижат к спинке.","yt":"ZD0-VB6x1rA","ych":"Александра Николаева"},{"id":"Dumbbell_Lunges","name":"Выпады с гантелями","group":"Ноги","muscles":"Квадрицепсы, ягодицы, приводящие, бицепс бедра","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Встань прямо, гантели держи в опущенных руках по бокам.","Сделай широкий шаг вперёд и опускайся, пока заднее колено почти не коснётся пола.","Держи корпус вертикально, переднее колено веди по линии носка.","Оттолкнись передней ногой и вернись в исходное положение.","Сделай все повторы на одну ногу или чередуй ноги."],"mistakes":["Шаг слишком короткий, пятка передней ноги отрывается от пола.","Корпус заваливается вперёд или в сторону.","Переднее колено уходит внутрь."],"tip":"Отталкивайся передней ногой через пятку и середину стопы, а не задней ногой.","yt":"vNrkKOiksCs","ych":"Евгений Есипович"},{"id":"Dumbbell_Rear_Lunge","name":"Обратные выпады с гантелями","group":"Ноги","muscles":"Квадрицепсы, ягодицы, приводящие, бицепс бедра","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Встань прямо, стопы на ширине таза, гантели в опущенных руках.","Сделай шаг назад одной ногой и опустись, пока заднее колено почти не коснётся пола.","Держи вес на передней ноге, корпус вертикально, колено над стопой.","Оттолкнись передней ногой и приставь заднюю ногу обратно.","Выполни повторы на одну ногу, затем смени ногу."],"mistakes":["Отталкиваешься задней ногой вместо передней.","Стопы стоят на одной линии, и теряется равновесие.","Колено с размаху бьётся об пол."],"tip":"Держи вес на пятке и середине передней стопы, задняя нога нужна только для равновесия.","yt":"RiiHGrzYMs8","ych":"PHYSICAL TRAINING"},{"id":"Split_Squat_with_Dumbbells","name":"Сплит-приседания с гантелями","group":"Ноги","muscles":"Квадрицепсы, ягодицы, приводящие, бицепс бедра","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Встань спиной к скамье и положи на неё носок задней ноги.","Переднюю стопу поставь на большой шаг вперёд, гантели держи в опущенных руках.","Опускайся вертикально вниз, сгибая переднее колено, пока бедро не станет параллельно полу.","Переднее колено веди по линии носка, корпус держи прямо.","Поднимайся, давя передней стопой в пол, после подхода смени ногу."],"mistakes":["Передняя стопа стоит слишком близко к скамье, пятка отрывается.","Отталкиваешься задней ногой вместо передней.","Колено передней ноги заваливается внутрь."],"tip":"Сначала найди устойчивую постановку стоп без веса и только потом бери гантели.","yt":"QUDLDF1boTU","ych":"Bodymaster - универсальные программы тре"},{"id":"Dumbbell_Step_Ups","name":"Зашагивания на скамью с гантелями","group":"Ноги","muscles":"Квадрицепсы, ягодицы, бицепс бедра, икроножные","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Встань перед скамьёй высотой примерно до колена, гантели держи в опущенных руках.","Поставь одну стопу на скамью целиком.","Поднимись, выпрямляя ногу на скамье, и приставь вторую ногу сверху.","Спускайся медленно, опуская свободную ногу и контролируя движение рабочей.","Выполни все повторы на одну ногу, затем смени ногу."],"mistakes":["Отталкиваешься нижней ногой от пола, а не поднимаешься верхней.","Скамья слишком высокая, таз перекашивается при подъёме.","Резко падаешь вниз при спуске."],"tip":"Не толкайся нижней ногой, весь подъём должен делать нога на скамье.","yt":"zpLCeGhBul0","ych":"ТВОЙ ТРЕНЕР: энциклопедия фитнеса"},{"id":"Leg_Extensions","name":"Разгибание ног в тренажёре","group":"Ноги","muscles":"Квадрицепсы","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Отрегулируй спинку так, чтобы колени совпадали с осью вращения тренажёра.","Поставь валик на низ голени над стопой и держись за рукоятки.","Выпрями ноги до конца и задержись на секунду в верхней точке.","Медленно опусти вес, не давая плитам стукнуться."],"mistakes":["Рывком забрасываешь вес, помогая себе корпусом.","Таз отрывается от сиденья.","Ось тренажёра не совпадает с коленом."],"tip":"Опускай вес медленно и подконтрольно, не бросай его вниз.","yt":"90q3AHfoAaw","ych":"Кузница Спорта"},{"id":"Standing_Calf_Raises","name":"Подъёмы на носки стоя","group":"Ноги","muscles":"Икроножные, камбаловидные","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":5,"unit":"кг","how":["Встань под валики тренажёра, подушечки стоп поставь на край платформы.","Выпрямись, колени держи прямыми, но не заблокированными.","Опусти пятки как можно ниже до растяжения в икрах.","Поднимись на носки как можно выше и задержись на секунду.","Опускайся медленно, без пружинящих отскоков внизу."],"mistakes":["Пружинишь внизу вместо паузы в растяжении.","Амплитуда слишком короткая, пятки почти не опускаются.","Помогаешь себе сгибанием коленей."],"tip":"Делай паузу в нижней точке, чтобы работали мышцы, а не пружинили сухожилия.","yt":"-5mLbj55tq0","ych":"Кузница Спорта"},{"id":"Seated_Calf_Raise","name":"Подъёмы на носки сидя","group":"Ноги","muscles":"Камбаловидные, икроножные","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Сядь в тренажёр и поставь подушечки стоп на край платформы.","Опусти валик на бёдра у коленей и сними упор.","Опусти пятки как можно ниже до растяжения в икрах.","Поднимись на носки максимально высоко и задержись на секунду."],"mistakes":["Пружинишь внизу и работаешь в короткой амплитуде.","Помогаешь себе руками или корпусом.","Стопа заваливается наружу, вес уходит на мизинцы."],"tip":"Работай медленно и в полной амплитуде, здесь она важнее веса.","yt":"ZKeBOJUGmyU","ych":"INSPIRE тренируйся с умом"},{"id":"Thigh_Adductor","name":"Сведение ног в тренажёре","group":"Ноги","muscles":"Приводящие мышцы бедра","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":5,"unit":"кг","how":["Сядь в тренажёр, прижми спину к спинке, внутреннюю сторону бёдер к подушкам.","Выставь стартовую ширину, где чувствуешь лёгкое растяжение без боли.","Сведи ноги плавным усилием и задержись на секунду.","Медленно разведи ноги обратно, не давая весу упасть."],"mistakes":["Стартовая позиция слишком широкая, растяжение болезненное.","Резко сводишь ноги и бьёшь подушки друг о друга.","Наклоняешься вперёд и помогаешь корпусом."],"tip":"Начинай с умеренной ширины, приводящие легко потянуть на большом весе.","yt":"MmvCv-yboB0","ych":"Спортивный Бро"},{"id":"Romanian_Deadlift","name":"Румынская тяга со штангой","group":"Ягодицы и задняя поверхность","muscles":"Бицепс бедра, ягодицы, разгибатели спины","equip":"Штанга","level":"опытный","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Встань прямо со штангой в руках, хват чуть шире бёдер, стопы на ширине таза.","Слегка согни колени и сохраняй этот угол до конца подхода.","Отводи таз назад, скользя грифом по ногам, пока не почувствуешь сильное растяжение сзади бедра.","Спину держи ровной, лопатки сведены, гриф всё время близко к ногам.","Вернись вверх, толкая таз вперёд и напрягая ягодицы."],"mistakes":["Округляешь спину, чтобы опуститься ниже.","Сильно сгибаешь колени, и тяга превращается в присед.","Гриф отходит от ног вперёд."],"tip":"Опускайся только до точки, где спина ещё ровная, обычно это середина голени.","yt":"bnuDUDfaUOM","ych":"Михаил Смалько"},{"id":"Stiff-Legged_Dumbbell_Deadlift","name":"Румынская тяга с гантелями","group":"Ягодицы и задняя поверхность","muscles":"Бицепс бедра, ягодицы, разгибатели спины","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Встань прямо, стопы на ширине таза, гантели держи перед бёдрами.","Слегка согни колени и сохраняй этот угол до конца подхода.","Отводи таз назад, опуская гантели вдоль ног до растяжения сзади бедра.","Держи спину ровной, а гантели близко к ногам.","Поднимись, выводя таз вперёд и сжимая ягодицы."],"mistakes":["Округляешь спину в нижней точке.","Гантели уходят вперёд от ног.","Наверху отклоняешься назад и прогибаешь поясницу."],"tip":"Думай не о наклоне вниз, а о том, чтобы отвести таз назад к стене.","yt":"w8618QnyZi8","ych":"Михаил Смалько"},{"id":"Barbell_Deadlift","name":"Становая тяга","group":"Ягодицы и задняя поверхность","muscles":"Разгибатели спины, ягодицы, бицепс бедра, квадрицепсы, трапеции","equip":"Штанга","level":"опытный","sets":3,"lo":6,"hi":8,"step":5,"unit":"кг","how":["Встань так, чтобы гриф был над серединой стопы, стопы на ширине таза.","Наклонись и возьми гриф хватом чуть шире ног, подведи голени к грифу.","Опусти таз, выпрями спину, сделай вдох и напряги пресс.","Поднимай штангу, давя ногами в пол и ведя гриф вплотную к ногам.","Наверху встань прямо без отклонения назад и опусти штангу тем же путём."],"mistakes":["Спина округляется при отрыве штанги от пола.","Таз поднимается раньше плеч, и тянешь одной спиной.","Гриф уходит вперёд от ног."],"tip":"Перед отрывом натяни гриф и напряги спину, не дёргай штангу с пола.","yt":"KddlE57Yjt0","ych":"Кузница Спорта"},{"id":"Barbell_Hip_Thrust","name":"Ягодичный мост со штангой (хип-траст)","group":"Ягодицы и задняя поверхность","muscles":"Ягодицы, бицепс бедра, квадрицепсы","equip":"Штанга","level":"опытный","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Сядь на пол спиной к скамье и прокати штангу с мягкой накладкой к тазу.","Обопрись нижним краем лопаток о скамью, стопы поставь на ширине плеч.","Поднимай таз, давя пятками в пол, до прямой линии от плеч до колен.","Наверху голени вертикальны, сожми ягодицы на секунду, подбородок прижат.","Опусти таз под контролем почти до пола."],"mistakes":["Прогибаешься в пояснице вместо разгибания в тазу.","Стопы стоят слишком далеко, нагрузка уходит в бицепс бедра.","Опираешься о скамью шеей, а не лопатками."],"tip":"Наверху держи рёбра опущенными и подкручивай таз, чтобы не прогибать поясницу.","yt":"1TY2VFEuko0","ych":"PHYSICAL TRAINING"},{"id":"Barbell_Glute_Bridge","name":"Ягодичный мост с пола","group":"Ягодицы и задняя поверхность","muscles":"Ягодицы, бицепс бедра","equip":"Штанга","level":"новичок","sets":3,"lo":10,"hi":15,"step":5,"unit":"кг","how":["Сядь на пол, прокати штангу с мягкой накладкой к тазу и ляг на спину.","Согни колени и поставь стопы на ширине плеч ближе к тазу.","Придерживая гриф руками, подними таз, давя пятками в пол.","Наверху сожми ягодицы на секунду, тело от плеч до колен в одну линию.","Медленно опусти таз до лёгкого касания пола."],"mistakes":["Прогибаешь поясницу вместо работы ягодиц.","Колени сводятся внутрь или разваливаются в стороны.","Опускаешь таз рывком и отбиваешь его от пола."],"tip":"Держи подбородок прижатым и рёбра опущенными, тогда движение пойдёт из таза, а не из поясницы.","yt":"DQv1IMQDbE4","ych":"PureGym"},{"id":"Single_Leg_Glute_Bridge","name":"Ягодичный мост на одной ноге","group":"Ягодицы и задняя поверхность","muscles":"Ягодицы, бицепс бедра","equip":"Свой вес","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"свой вес + кг","how":["Ляг на спину, согни колени и поставь стопы на пол ближе к тазу.","Подними одну ногу, подтянув колено к груди.","Давя пяткой опорной ноги, подними таз до прямой линии от плеча до колена.","Задержись на секунду, сжав ягодицу, и медленно опустись.","Сделай все повторы на одну ногу, затем смени ногу."],"mistakes":["Таз перекашивается в сторону поднятой ноги.","Прогибаешь поясницу в верхней точке.","Опорная стопа стоит далеко, и сводит заднюю поверхность бедра."],"tip":"Держи таз ровным, обе его стороны должны подниматься на одну высоту.","yt":"yNAzphSGP5c","ych":"Кузница Спорта"},{"id":"Lying_Leg_Curls","name":"Сгибание ног лёжа","group":"Ягодицы и задняя поверхность","muscles":"Бицепс бедра, икроножные","equip":"Тренажёр","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"кг","how":["Ляг лицом вниз так, чтобы колени были сразу за краем скамьи.","Поставь валик на голени чуть выше пяток, держись за рукоятки.","Прижми таз к скамье и согни ноги как можно сильнее, задержись на секунду.","Медленно опусти вес до почти прямых ног."],"mistakes":["Таз поднимается от скамьи во время сгибания.","Рывком забрасываешь вес и бросаешь его вниз.","Ноги не выпрямляются внизу, амплитуда неполная."],"tip":"Прижимай таз к скамье, иначе часть работы забирает поясница.","yt":"kHA7OtTBjAA","ych":"Спортивный Бро"},{"id":"Seated_Leg_Curl","name":"Сгибание ног сидя","group":"Ягодицы и задняя поверхность","muscles":"Бицепс бедра, икроножные","equip":"Тренажёр","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"кг","how":["Отрегулируй спинку так, чтобы колени совпадали с осью вращения тренажёра.","Положи голени на валик чуть выше пяток и плотно опусти фиксатор на бёдра.","Согни ноги как можно сильнее и задержись на секунду.","Медленно верни ноги вперёд до почти полного выпрямления."],"mistakes":["Фиксатор бёдер затянут слабо, таз съезжает вперёд.","Рывками забрасываешь и бросаешь вес.","Работаешь в короткой амплитуде."],"tip":"Плотно зафиксируй бёдра, чтобы таз не съезжал и двигались только колени.","yt":"_SRfJsiqIM8","ych":"BodySportal.com"},{"id":"Hyperextensions_Back_Extensions","name":"Гиперэкстензия","group":"Ягодицы и задняя поверхность","muscles":"Разгибатели спины, ягодицы, бицепс бедра","equip":"Свой вес","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"свой вес + кг","how":["Настрой верхний валик так, чтобы его край был чуть ниже тазовых костей.","Закрепи пятки под нижними валиками и скрести руки на груди.","Наклонись вперёд с ровной спиной до растяжения сзади бедра.","Поднимись до прямой линии тела, напрягая ягодицы.","Для усложнения держи у груди диск или гантель."],"mistakes":["Поднимаешься выше линии тела и переразгибаешь поясницу.","Раскачиваешься и делаешь рывки.","Валик стоит слишком высоко и мешает наклону."],"tip":"Наверху остановись на прямой линии тела и не прогибайся дальше.","yt":"b5xKWsrAjxM","ych":"ТВОЙ ТРЕНЕР: энциклопедия фитнеса"},{"id":"Glute_Kickback","name":"Отведение ноги назад на четвереньках","group":"Ягодицы и задняя поверхность","muscles":"Ягодицы, бицепс бедра","equip":"Свой вес","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"свой вес + кг","how":["Встань на четвереньки, колени под тазом, ладони под плечами.","Напряги пресс и держи спину ровной.","Подними одну ногу назад и вверх, сохраняя прямой угол в колене, до линии корпуса.","Сожми ягодицу наверху на секунду и медленно опусти колено.","Выполни повторы на одну ногу, затем смени ногу."],"mistakes":["Поднимаешь ногу выше корпуса и прогибаешь поясницу.","Делаешь махи по инерции.","Таз разворачивается в сторону рабочей ноги."],"tip":"Поднимай ногу только до уровня спины, движение должно идти из ягодицы, а не из поясницы.","yt":"K8FpfXCt3w4","ych":"ТВОЙ ТРЕНЕР: энциклопедия фитнеса"},{"id":"Thigh_Abductor","name":"Разведение ног в тренажёре","group":"Ягодицы и задняя поверхность","muscles":"Средняя ягодичная, малая ягодичная, большая ягодичная","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":5,"unit":"кг","how":["Сядь в тренажёр, прижми спину к спинке, подушки поставь на внешнюю сторону бёдер.","Возьмись за рукоятки и держи корпус неподвижно.","Разведи ноги плавным усилием как можно шире и задержись на секунду.","Медленно сведи ноги, не давая плитам стукнуться."],"mistakes":["Раскачиваешь корпус и помогаешь себе рывком.","Бросаешь вес на возврате.","Вес слишком большой, и амплитуда получается короткой."],"tip":"Задерживайся на секунду в крайней точке и возвращай вес медленно.","yt":"mSziPop9F2k","ych":"Олександр Попенко"},{"id":"Pull_Through","name":"Тяга каната между ног (пул-тру)","group":"Ягодицы и задняя поверхность","muscles":"Ягодицы, бицепс бедра, разгибатели спины","equip":"Блок","level":"новичок","sets":3,"lo":12,"hi":15,"step":5,"unit":"кг","how":["Закрепи канат на нижнем блоке и встань к тренажёру спиной, канат между ног.","Отойди на пару шагов, поставь стопы шире плеч и слегка согни колени.","Отводи таз назад, пропуская канат между ног, спина ровная, руки прямые.","Выпрямись, толкая таз вперёд и сжимая ягодицы наверху."],"mistakes":["Тянешь канат руками вместо разгибания в тазу.","Приседаешь вместо наклона с отведением таза.","Округляешь спину в нижней точке."],"tip":"Двигай таз назад и вперёд, а руки оставляй прямыми, они просто держат канат.","yt":"fbF4_pn_0xc","ych":"Live Lean TV Daily Exercises"},{"id":"Barbell_Bench_Press_-_Medium_Grip","name":"Жим штанги лёжа","group":"Грудь","muscles":"Грудные, передние дельты, трицепс","equip":"Штанга","level":"новичок","sets":3,"lo":6,"hi":10,"step":5,"unit":"кг","how":["Ляг так, чтобы глаза были под грифом, ступни плотно упри в пол.","Возьмись хватом чуть шире плеч, сведи и опусти лопатки, сними штангу на прямые руки.","На вдохе медленно опусти гриф к низу груди, локти держи примерно под 45° к корпусу.","Коснись груди без отбива и на выдохе выжми штангу вверх к линии плеч.","Держи лопатки и таз прижатыми к скамье весь подход."],"mistakes":["Локти разведены в стороны под прямым углом к корпусу.","Отбив штанги от груди и отрыв таза от скамьи.","Лопатки не сведены, плечи уходят вперёд в верхней точке."],"tip":"Держи лопатки сведёнными и опущенными, а локти примерно под 45° к корпусу, так плечи в безопасности.","yt":"nWo_m0REGMA","ych":"Михаил Смалько"},{"id":"Barbell_Incline_Bench_Press_-_Medium_Grip","name":"Жим штанги на наклонной скамье","group":"Грудь","muscles":"Верх грудных, передние дельты, трицепс","equip":"Штанга","level":"новичок","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Выставь наклон скамьи 30–45°, ляг и плотно упри ступни в пол.","Возьмись хватом чуть шире плеч, сведи и опусти лопатки, сними штангу.","На вдохе плавно опусти гриф к верху груди, чуть ниже ключиц.","На выдохе выжми штангу вверх над плечами, не отрывая таз и лопатки."],"mistakes":["Слишком крутой наклон скамьи, и нагрузка уходит в плечи.","Гриф опускается к шее или к середине груди.","Таз отрывается от скамьи, корпус выгибается мостом."],"tip":"Держи локти примерно под 45° к корпусу и не давай плечам подниматься к ушам.","yt":"xRKOvtLwJZE","ych":"Кузница Спорта"},{"id":"Dumbbell_Bench_Press","name":"Жим гантелей лёжа","group":"Грудь","muscles":"Грудные, передние дельты, трицепс","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Сядь на край скамьи, поставь гантели на бёдра и ляг, помогая коленями поднять их.","Сведи и опусти лопатки, выжми гантели над грудью, ладонями в сторону ног.","На вдохе медленно опусти гантели по бокам груди, локти примерно под 45° к корпусу.","На выдохе выжми гантели вверх, слегка сводя их над грудью без удара.","Закончив, верни гантели на бёдра и только потом садись."],"mistakes":["Слишком глубокое опускание гантелей с потерей контроля в плечах.","Локти разведены строго в стороны.","Гантели бросают в стороны сразу после подхода."],"tip":"Опускай гантели до уровня груди, не глубже, и держи лопатки сведёнными весь подход.","yt":"EDEYzHWbn8c","ych":"Михаил Смалько"},{"id":"Incline_Dumbbell_Press","name":"Жим гантелей на наклонной скамье","group":"Грудь","muscles":"Верх грудных, передние дельты, трицепс","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Выставь наклон 30–45°, сядь с гантелями на бёдрах и откинься, поднимая их коленями.","Выжми гантели над плечами ладонями вперёд, лопатки сведи и прижми к скамье.","На вдохе медленно опусти гантели к верху груди, локти примерно под 45° к корпусу.","На выдохе выжми гантели вверх по небольшой дуге, сводя их над грудью.","В конце подхода верни гантели на бёдра и только потом садись."],"mistakes":["Слишком крутая скамья превращает упражнение в жим на плечи.","Локти уходят строго в стороны, плечи поднимаются к ушам.","Отбив гантелей из нижней точки и неполная амплитуда."],"tip":"Держи лопатки сведёнными и опущенными всё время, тогда работает грудь, а не плечи.","yt":"ZixeFw_iHVY","ych":"Михаил Смалько"},{"id":"Dumbbell_Flyes","name":"Разведение гантелей лёжа","group":"Грудь","muscles":"Грудные, передние дельты","equip":"Гантели","level":"новичок","sets":3,"lo":10,"hi":15,"step":2,"unit":"кг в руке","how":["Ляг на горизонтальную скамью и выжми гантели над грудью, ладони смотрят друг на друга.","Чуть согни локти и сохраняй этот угол весь подход.","На вдохе медленно разведи руки по широкой дуге до растяжения в груди.","На выдохе сведи гантели по той же дуге, думая о сжатии груди."],"mistakes":["Локти сгибаются и разгибаются, разведение превращается в жим.","Руки опускаются заметно ниже линии корпуса.","Слишком тяжёлый вес, из-за которого теряется контроль внизу."],"tip":"Не опускай локти ниже линии корпуса и держи их слегка согнутыми, так ты бережёшь плечи.","yt":"q7DoKfJR14A","ych":"Михаил Смалько"},{"id":"Cable_Crossover","name":"Сведение рук в кроссовере","group":"Грудь","muscles":"Грудные, передние дельты","equip":"Блок","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Поставь блоки в верхнее положение, возьми рукояти и сделай шаг вперёд.","Встань в небольшую разножку, чуть наклони корпус вперёд, локти слегка согни.","На выдохе сведи руки по дуге вниз и вперёд, чтобы кисти встретились перед низом груди.","Задержись на секунду, сожми грудь и медленно разведи руки до растяжения."],"mistakes":["Локти сгибаются в конце, и движение превращается в жим вниз.","Раскачивание корпусом и рывки весом.","Руки уходят слишком далеко назад за линию плеч."],"tip":"Держи угол в локтях постоянным и двигай руками только в плечевом суставе, корпус неподвижен.","yt":"9fk7dXIjKus","ych":"Кузница Спорта"},{"id":"Butterfly","name":"Сведение рук в тренажёре (бабочка)","group":"Грудь","muscles":"Грудные, передние дельты","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Отрегулируй сиденье так, чтобы рукояти были на уровне груди, а плечи параллельны полу.","Прижми спину к спинке, сведи лопатки и возьмись за рукояти, локти чуть согнуты.","На выдохе сведи рукояти перед грудью и задержись на секунду.","На вдохе медленно разведи руки до лёгкого растяжения в груди."],"mistakes":["Сиденье стоит слишком низко или высоко, нагрузка уходит в плечи.","Спина отрывается от спинки, плечи подаются вперёд.","Резкий возврат с ударом грузов друг о друга."],"tip":"Не отводи руки дальше линии корпуса, глубокое растяжение перегружает переднюю часть плеча.","yt":"21QYTOJXy7A","ych":"Михаил Смалько"},{"id":"Leverage_Chest_Press","name":"Жим от груди в тренажёре","group":"Грудь","muscles":"Грудные, передние дельты, трицепс","equip":"Тренажёр","level":"новичок","sets":3,"lo":10,"hi":15,"step":5,"unit":"кг","how":["Отрегулируй сиденье так, чтобы рукояти были на уровне середины или низа груди.","Прижми спину к спинке, сведи и опусти лопатки, грудь держи раскрытой.","На выдохе выжми рукояти вперёд почти до выпрямления рук.","Медленно верни рукояти назад, не опуская вес на упоры до конца подхода."],"mistakes":["Сиденье стоит слишком высоко, рукояти оказываются у шеи.","Плечи отрываются от спинки и уходят вперёд.","Вес ударяется об упор между повторениями."],"tip":"Держи локти примерно под 45° к корпусу, а лопатки прижатыми к спинке.","yt":"mO-nhSx0Ues","ych":"NEF New Era of Fitness"},{"id":"Pushups","name":"Отжимания от пола","group":"Грудь","muscles":"Грудные, трицепс, передние дельты, мышцы кора","equip":"Свой вес","level":"новичок","sets":3,"lo":10,"hi":20,"step":2.5,"unit":"свой вес + кг","how":["Поставь ладони чуть шире плеч, тело держи прямой линией от головы до пяток.","Напряги пресс и ягодицы, чтобы таз не провисал и не поднимался.","На вдохе опускайся, пока грудь почти не коснётся пола, локти примерно под 45° к корпусу.","На выдохе выжми себя вверх до прямых рук, сохраняя корпус ровным."],"mistakes":["Таз провисает или ягодицы задраны вверх.","Локти разведены в стороны под прямым углом.","Неполная амплитуда, опускание всего на несколько сантиметров."],"tip":"Если не выходит 10 чистых повторений, начни с отжиманий от скамьи, а позже добавь блин на спину.","yt":"PiG-gkXvIV8","ych":"Михаил Смалько"},{"id":"Dips_-_Chest_Version","name":"Отжимания на брусьях (на грудь)","group":"Грудь","muscles":"Нижняя часть грудных, трицепс, передние дельты","equip":"Свой вес","level":"опытный","sets":3,"lo":8,"hi":12,"step":2.5,"unit":"свой вес + кг","how":["Выйди в упор на прямых руках над брусьями, плечи опусти от ушей.","Наклони корпус вперёд примерно на 30°, локти слегка разведи в стороны.","На вдохе медленно опускайся до лёгкого растяжения в груди.","На выдохе выжми себя вверх до прямых рук, сохраняя наклон корпуса."],"mistakes":["Слишком глубокое опускание с болью в передней части плеча.","Корпус вертикально, и нагрузка уходит в трицепс.","Раскачивание ногами и рывки из нижней точки."],"tip":"Не опускайся глубже, чем плечи чуть ниже локтей, и держи плечи опущенными от ушей.","yt":"St9izqb4UW8","ych":"Михаил Смалько"},{"id":"Standing_Military_Press","name":"Жим штанги стоя","group":"Плечи","muscles":"Передние дельты, средние дельты, трицепс, верх грудных, мышцы кора","equip":"Штанга","level":"новичок","sets":3,"lo":6,"hi":10,"step":2.5,"unit":"кг","how":["Сними штангу со стоек хватом чуть шире плеч, гриф лежит на ключицах.","Поставь ноги на ширине плеч, напряги ягодицы и пресс, предплечья держи вертикально.","На выдохе выжми гриф строго вверх, слегка убрав голову назад, чтобы он прошёл мимо лица.","Вверху выпрями руки и подай голову вперёд под гриф.","На вдохе медленно опусти штангу обратно на ключицы."],"mistakes":["Прогиб в пояснице и отклонение корпуса назад.","Гриф уходит вперёд по дуге вокруг лица.","Подсед и толчок ногами вместо чистого жима."],"tip":"Сжимай ягодицы и пресс перед каждым повторением, чтобы поясница не прогибалась.","yt":"rLTulc8Gbe8","ych":"Михаил Смалько"},{"id":"Dumbbell_Shoulder_Press","name":"Жим гантелей сидя","group":"Плечи","muscles":"Передние дельты, средние дельты, трицепс","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Поставь спинку скамьи почти вертикально, сядь и закинь гантели к плечам с помощью бёдер.","Прижми спину к спинке, разверни ладони вперёд, локти держи чуть впереди корпуса.","На выдохе выжми гантели вверх, сводя их над головой без удара.","На вдохе медленно опусти гантели примерно до уровня ушей или подбородка."],"mistakes":["Сильный прогиб в пояснице и отрыв спины от спинки.","Локти разведены строго в стороны и уходят слишком низко.","Удар гантелей вверху и потеря контроля."],"tip":"Держи локти немного впереди корпуса, а не строго в стороны, так плечевому суставу комфортнее.","yt":"X5bgyaiWoJI","ych":"Кузница Спорта"},{"id":"Machine_Shoulder_Military_Press","name":"Жим в тренажёре для плеч","group":"Плечи","muscles":"Передние дельты, средние дельты, трицепс","equip":"Тренажёр","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"кг","how":["Отрегулируй сиденье так, чтобы рукояти в начале были на уровне плеч.","Прижми спину к спинке, возьмись за рукояти, локти направь вниз и чуть вперёд.","На выдохе выжми рукояти вверх почти до выпрямления рук.","На вдохе медленно опусти рукояти до уровня плеч, не роняя вес на упоры."],"mistakes":["Поясница отрывается от спинки, корпус выгибается.","Плечи поднимаются к ушам во время жима.","Вес бросают вниз с ударом грузов."],"tip":"Держи лопатки прижатыми к спинке и не поднимай плечи к ушам.","yt":"Jm4WjdJ8J9E","ych":"Geography Fitness"},{"id":"Side_Lateral_Raise","name":"Махи гантелями в стороны","group":"Плечи","muscles":"Средние дельты, передние дельты, трапеции","equip":"Гантели","level":"новичок","sets":3,"lo":12,"hi":15,"step":1,"unit":"кг в руке","how":["Встань прямо, гантели у бёдер, корпус чуть наклони вперёд.","Слегка согни локти и сохраняй этот угол весь подход.","На выдохе подними гантели через стороны до уровня плеч, ведя движение локтями.","На вдохе медленно опусти гантели, не бросая их вниз."],"mistakes":["Раскачивание корпусом и рывки ради большого веса.","Плечи поднимаются к ушам, и работают трапеции.","Кисти оказываются выше локтей в верхней точке."],"tip":"Возьми лёгкий вес и думай, что отводишь гантели в стороны, а не поднимаешь вверх.","yt":"SuyiAEszi-c","ych":"Олександр Попенко","ys":1},{"id":"Front_Dumbbell_Raise","name":"Подъёмы гантелей перед собой","group":"Плечи","muscles":"Передние дельты, верх грудных","equip":"Гантели","level":"новичок","sets":3,"lo":12,"hi":15,"step":1,"unit":"кг в руке","how":["Встань прямо, держи гантели перед бёдрами, ладони смотрят на тебя.","Напряги пресс и ягодицы, чтобы корпус оставался неподвижным.","На выдохе подними одну гантель вперёд до уровня плеч, локоть слегка согнут.","Задержись на секунду и медленно опусти гантель, одновременно поднимая другую."],"mistakes":["Раскачивание корпусом и заброс гантели инерцией.","Подъём сильно выше плеч с подъёмом плеч к ушам.","Быстрое опускание без контроля."],"tip":"Передние дельты много работают в жимах, поэтому здесь хватает лёгкого веса и чистой техники.","yt":"7Sq_kxLBeVQ","ych":"Кузница Спорта"},{"id":"Seated_Bent-Over_Rear_Delt_Raise","name":"Махи в наклоне на заднюю дельту","group":"Плечи","muscles":"Задние дельты, средняя часть трапеций, ромбовидные","equip":"Гантели","level":"опытный","sets":3,"lo":12,"hi":15,"step":1,"unit":"кг в руке","how":["Сядь на край скамьи, ноги вместе, гантели поставь на пол за голенями.","Наклонись вперёд с прямой спиной, грудь почти к бёдрам, возьми гантели ладонями друг к другу.","Слегка согни локти и на выдохе подними гантели через стороны до параллели с полом.","Задержись на секунду и медленно опусти гантели вниз."],"mistakes":["Корпус поднимается и раскачивается вместо работы плечами.","Руки уходят назад к поясу, а не в стороны.","Сильное сведение лопаток, и нагрузка уходит в спину."],"tip":"Возьми лёгкий вес и разводи руки строго в стороны, будто тянешь гантели к стенам.","yt":"8aidwLVg_IE","ych":"Олександр Попенко"},{"id":"Reverse_Machine_Flyes","name":"Обратная бабочка в тренажёре","group":"Плечи","muscles":"Задние дельты, средняя часть трапеций, ромбовидные","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Сядь лицом к спинке, отрегулируй сиденье так, чтобы рукояти были на уровне плеч.","Прижми грудь к спинке и возьмись за рукояти перед собой, локти чуть согни.","На выдохе разведи руки по дуге в стороны и назад до линии корпуса.","Задержись на секунду и медленно верни рукояти вперёд."],"mistakes":["Локти сгибаются, и вместо разведения получается тяга руками.","Плечи поднимаются к ушам.","Грудь отрывается от спинки, корпус раскачивается."],"tip":"Держи плечи опущенными, а угол в локтях постоянным, двигай руками только в плечевом суставе.","yt":"Iww1W9LSOio","ych":"Ефим Баранов"},{"id":"Face_Pull","name":"Тяга каната к лицу","group":"Плечи","muscles":"Задние дельты, средняя часть трапеций, ромбовидные, вращательная манжета плеча","equip":"Блок","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Закрепи канат на блоке на уровне лица или чуть выше и возьмись за концы.","Отойди на шаг назад, встань устойчиво, руки вытяни перед собой.","На выдохе тяни канат к лицу, разводя концы в стороны к ушам.","Держи локти высоко на уровне плеч, в конце кисти окажутся по бокам головы.","Задержись на секунду и медленно верни руки вперёд."],"mistakes":["Отклонение корпуса назад и тяга весом тела.","Локти опускаются, и упражнение превращается в тягу к груди.","Слишком большой вес и неполная амплитуда."],"tip":"Возьми умеренный вес, здесь важны высокие локти и пауза в конце, а не килограммы.","yt":"1tyeCkHmA1k","ych":"PHYSICAL TRAINING"},{"id":"Triceps_Pushdown_-_Rope_Attachment","name":"Разгибания на трицепс с канатом","group":"Руки","muscles":"Трицепс","equip":"Блок","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Закрепи канат на верхнем блоке и возьмись нейтральным хватом, ладони друг к другу.","Встань прямо с лёгким наклоном вперёд, прижми локти к бокам.","На выдохе разогни руки вниз до конца, разводя концы каната в стороны.","Медленно верни канат вверх, пока предплечья не окажутся чуть выше параллели с полом."],"mistakes":["Локти ходят вперёд-назад и отходят от корпуса.","Наваливание весом тела на канат.","Руки не разгибаются до конца внизу."],"tip":"Представь, что локти прибиты к бокам, двигаются только предплечья.","yt":"NcZIZHACTtg","ych":"Спортивный Бро"},{"id":"Triceps_Pushdown","name":"Разгибания на трицепс с рукоятью","group":"Руки","muscles":"Трицепс","equip":"Блок","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"кг","how":["Закрепи прямую или изогнутую рукоять на верхнем блоке, возьмись хватом сверху на ширине плеч.","Встань прямо с лёгким наклоном вперёд, прижми локти к бокам.","На выдохе разогни руки до конца, опуская рукоять к бёдрам.","Медленно верни рукоять вверх до уровня груди, не отводя локти от корпуса."],"mistakes":["Локти уходят вперёд, и подключаются плечи.","Раскачивание корпусом и рывки весом.","Запястья прогибаются под весом рукояти."],"tip":"Держи запястья ровными, а локти прижатыми к корпусу весь подход.","yt":"AuA1webgdBQ","ych":"Bodymaster - универсальные программы тре"},{"id":"EZ-Bar_Skullcrusher","name":"Французский жим лёжа","group":"Руки","muscles":"Трицепс, предплечья","equip":"Штанга","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"кг","how":["Ляг на скамью, возьми изогнутый гриф узким хватом и выпрями руки над грудью.","Слегка отведи руки назад к голове, чтобы трицепс оставался под нагрузкой.","На вдохе согни локти и медленно опусти гриф ко лбу или чуть за голову.","На выдохе разогни руки, не двигая плечами и не разводя локти."],"mistakes":["Локти разъезжаются в стороны.","Плечи двигаются, и упражнение превращается в жим.","Гриф опускается быстро и без контроля над головой."],"tip":"Опускай гриф медленно и начинай с лёгкого веса, чтобы поберечь локти.","yt":"v1K0H8A_AME","ych":"ТВОЙ ТРЕНЕР: энциклопедия фитнеса"},{"id":"Standing_Dumbbell_Triceps_Extension","name":"Разгибание гантели из-за головы","group":"Руки","muscles":"Трицепс","equip":"Гантели","level":"новичок","sets":3,"lo":10,"hi":15,"step":2,"unit":"кг","how":["Встань прямо, возьми одну гантель обеими ладонями под верхний диск и подними над головой.","Напряги пресс и ягодицы, локти направь вверх и держи близко к голове.","На вдохе медленно опусти гантель за голову по дуге до растяжения трицепса.","На выдохе разогни руки вверх, двигая только предплечьями."],"mistakes":["Локти широко расходятся в стороны.","Поясница прогибается во время разгибания.","Короткая амплитуда, гантель не опускается за голову."],"tip":"Если поясница прогибается, делай упражнение сидя на скамье со спинкой.","yt":"H6E9p0GXNhY","ych":"Bodymaster - универсальные программы тре"},{"id":"Close-Grip_Barbell_Bench_Press","name":"Жим штанги узким хватом","group":"Руки","muscles":"Трицепс, грудные, передние дельты","equip":"Штанга","level":"новичок","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Ляг на скамью, возьмись за гриф на ширине плеч и сними штангу на прямые руки.","Сведи и опусти лопатки, ступни плотно упри в пол.","На вдохе медленно опусти гриф к низу груди, держа локти близко к корпусу.","На выдохе выжми штангу вверх до прямых рук, не разводя локти."],"mistakes":["Слишком узкий хват, из-за которого болят запястья.","Локти разводятся в стороны, как в обычном жиме.","Отбив штанги от груди."],"tip":"Хвата на ширине плеч достаточно, более узкий хват только перегружает запястья.","yt":"Er_XTfK3Auc","ych":"Михаил Смалько"},{"id":"Bench_Dips","name":"Обратные отжимания от скамьи","group":"Руки","muscles":"Трицепс, передние дельты, грудные","equip":"Свой вес","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"свой вес + кг","how":["Сядь на край скамьи, упрись в неё ладонями на ширине плеч, пальцы вперёд.","Сдвинь таз со скамьи вперёд, ноги вытяни или согни в коленях для облегчения.","На вдохе согни локти и опустись, пока они не согнутся примерно под 90°.","На выдохе выпрями руки и поднимись, держа спину близко к скамье."],"mistakes":["Слишком глубокое опускание, перегружающее переднюю часть плеча.","Локти разводятся в стороны.","Спина далеко от скамьи, плечи заваливаются вперёд."],"tip":"Не опускайся ниже 90° в локтях, более глубокая амплитуда здесь опасна для плеч.","yt":"h9IgVgOls8k","ych":"Олександр Попенко"},{"id":"Pullups","name":"Подтягивания","group":"Спина","muscles":"Широчайшие, бицепс, середина спины, задние дельты","equip":"Свой вес","level":"опытный","sets":3,"lo":6,"hi":10,"step":2.5,"unit":"свой вес + кг","how":["Возьмись за перекладину прямым хватом чуть шире плеч и повисни на прямых руках.","Опусти плечи вниз, напряги пресс и ягодицы, ноги держи вместе.","Тянись грудью к перекладине, ведя локти вниз к рёбрам.","Подними подбородок выше перекладины без рывка и раскачки.","Опускайся плавно до почти прямых рук, не бросая тело вниз."],"mistakes":["Раскачка и рывки ногами вместо работы спиной.","Неполная амплитуда: не опускаешься до прямых рук.","Плечи поднимаются к ушам в начале движения."],"tip":"Начинай каждый повтор с опускания лопаток, а не со сгибания рук, тогда работает спина.","yt":"PD0mm8MUTqI","ych":"Спортивные советы","ys":1},{"id":"Wide-Grip_Lat_Pulldown","name":"Тяга верхнего блока широким хватом","group":"Спина","muscles":"Широчайшие, бицепс, середина спины, задние дельты","equip":"Блок","level":"новичок","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Подстрой валики так, чтобы бёдра были плотно прижаты, и сядь ровно.","Возьмись за рукоять прямым хватом шире плеч и слегка отклонись назад.","Опусти лопатки и тяни рукоять к верху груди, ведя локти вниз и назад.","Внизу на секунду сведи лопатки.","Плавно верни рукоять вверх до полного выпрямления рук."],"mistakes":["Сильный отклон назад и раскачка корпусом.","Тяга за голову вместо тяги к груди.","Тянешь руками и предплечьями, забывая про спину."],"tip":"Думай, что тянешь локтями, а кисти просто держат рукоять.","yt":"_bPdnFwrLhw","ych":"Спортивный Бро"},{"id":"Close-Grip_Front_Lat_Pulldown","name":"Тяга верхнего блока узким хватом","group":"Спина","muscles":"Широчайшие, бицепс, середина спины, задние дельты","equip":"Блок","level":"новичок","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Сядь, зафиксируй бёдра под валиками, спину держи прямой.","Возьмись за рукоять хватом уже плеч, слегка отклонись назад и выведи грудь.","Тяни рукоять к верху груди, ведя локти вниз вдоль корпуса.","Внизу сожми спину на секунду, затем плавно отпусти рукоять вверх."],"mistakes":["Раскачка корпусом, чтобы помочь себе инерцией.","Руки не выпрямляются вверху, широчайшие не растягиваются.","Плечи поднимаются к ушам во время тяги."],"tip":"Вверху дай спине растянуться, а каждую тягу начинай с опускания лопаток.","yt":"QHlcYxtJE8k","ych":"KRASNOVFITNESS"},{"id":"Seated_Cable_Rows","name":"Тяга нижнего блока сидя","group":"Спина","muscles":"Середина спины, широчайшие, бицепс, задние дельты","equip":"Блок","level":"новичок","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Сядь, упрись ногами в платформу, колени слегка согни.","Возьмись за узкую рукоять с параллельным хватом и выпрями спину под прямым углом к ногам.","Тяни рукоять к низу живота, ведя локти назад вдоль корпуса.","В конце сведи лопатки и задержись на секунду.","Плавно верни рукоять вперёд, сохраняя спину ровной."],"mistakes":["Раскачка корпусом вперёд-назад вместо работы спины.","Спина округляется, когда тянешься за рукоятью.","Плечи поднимаются к ушам во время тяги."],"tip":"Корпус почти неподвижен, двигаются только руки и лопатки.","yt":"CtP0tKV6DdM","ych":"Спортивный Бро"},{"id":"Bent_Over_Barbell_Row","name":"Тяга штанги в наклоне","group":"Спина","muscles":"Середина спины, широчайшие, бицепс, задние дельты, разгибатели спины","equip":"Штанга","level":"новичок","sets":3,"lo":6,"hi":10,"step":5,"unit":"кг","how":["Возьми штангу прямым хватом чуть шире плеч, колени слегка согни.","Наклонись, отводя таз назад, почти до параллели корпуса с полом, спина ровная.","Тяни штангу к низу живота, ведя локти назад вдоль корпуса.","Наверху сведи лопатки, затем плавно опусти штангу до прямых рук."],"mistakes":["Круглая спина, особенно в пояснице.","Корпус поднимается с каждым повтором, тяга превращается в рывок.","Слишком большой вес, который приходится забрасывать спиной."],"tip":"Держи поясницу в нейтральном положении и пресс в напряжении весь подход.","yt":"A2qowMyI8zY","ych":"Спортивные советы","ys":1},{"id":"One-Arm_Dumbbell_Row","name":"Тяга гантели одной рукой","group":"Спина","muscles":"Середина спины, широчайшие, бицепс, задние дельты","equip":"Гантели","level":"новичок","sets":3,"lo":8,"hi":12,"step":2,"unit":"кг в руке","how":["Упрись коленом и ладонью одной стороны в скамью, спину держи параллельно полу.","Возьми гантель свободной рукой, ладонь смотрит к корпусу.","Тяни гантель к поясу, ведя локоть назад вдоль тела.","Наверху сожми спину, затем плавно опусти гантель до прямой руки.","Сделай все повторы и смени руку."],"mistakes":["Скручивание корпуса, чтобы закинуть гантель повыше.","Тяга рывком за счёт раскачки корпуса.","Округлённая спина и провисание в опорном плече."],"tip":"Представь, что тянешь локоть к заднему карману, а не гантель к плечу.","yt":"l4ByvIJcdi0","ych":"BodySportal.com"},{"id":"Straight-Arm_Pulldown","name":"Пуловер в блоке прямыми руками","group":"Спина","muscles":"Широчайшие, большая круглая, длинная головка трицепса, задние дельты","equip":"Блок","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Встань лицом к верхнему блоку и возьмись за прямую рукоять хватом чуть шире плеч.","Отойди на шаг, наклони корпус вперёд примерно на 30 градусов, руки почти прямые.","Опусти рукоять по дуге к бёдрам, не сгибая локти.","Внизу напряги широчайшие, затем плавно верни руки вверх."],"mistakes":["Сгибаешь локти и превращаешь упражнение в разгибание на трицепс.","Раскачиваешь корпус, помогая себе спиной и ногами.","Плечи поднимаются вверх, шея напрягается."],"tip":"Локти слегка согнуты и зафиксированы, движение идёт только в плечевом суставе.","yt":"pIVrPdVufno","ych":"Кузница Спорта"},{"id":"T-Bar_Row_with_Handle","name":"Тяга Т-грифа","group":"Спина","muscles":"Середина спины, широчайшие, бицепс, задние дельты, разгибатели спины","equip":"Штанга","level":"новичок","sets":3,"lo":8,"hi":12,"step":5,"unit":"кг","how":["Закрепи один конец грифа в углу или станке, повесь блины на свободный конец.","Встань над грифом и возьмись за рукоять-треугольник, заведённую под гриф у блинов.","Отведи таз назад, наклони корпус, спину держи ровной, руки прямые.","Тяни вес к верху живота, сводя лопатки, без рывков.","После короткой паузы плавно опусти гриф до прямых рук."],"mistakes":["Округлённая поясница в наклоне.","Рывки корпусом и подбрасывание веса.","Слишком короткая амплитуда из-за большого веса."],"tip":"Колени слегка согнуты, пресс напряжён, поясница всё время ровная.","yt":"hMQOsKWEx_E","ych":"STROITEL тренажерный зал / спортивное пи"},{"id":"Dumbbell_Shrug","name":"Шраги с гантелями","group":"Спина","muscles":"Верхние трапеции, предплечья","equip":"Гантели","level":"новичок","sets":3,"lo":12,"hi":15,"step":2,"unit":"кг в руке","how":["Встань прямо с гантелями в опущенных руках, ладони смотрят к корпусу.","Подними плечи строго вверх к ушам, руки остаются прямыми.","Задержись наверху на секунду, сжав трапеции.","Медленно опусти плечи до полного растяжения."],"mistakes":["Круговые движения плечами: они не нужны и нагружают сустав.","Сгибание рук в локтях, подключается бицепс.","Короткая амплитуда и рывки с большим весом."],"tip":"Голову держи ровно и не вытягивай шею вперёд, двигаются только плечи.","yt":"cdjovZj0BMA","ych":"Евгений Есипович"},{"id":"Barbell_Curl","name":"Подъём штанги на бицепс","group":"Руки","muscles":"Бицепс, плечевая мышца, предплечья","equip":"Штанга","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"кг","how":["Встань прямо и возьми штангу хватом снизу на ширине плеч.","Прижми локти к корпусу и зафиксируй их.","Согни руки и подними штангу к плечам, двигаются только предплечья.","Наверху сожми бицепс, затем медленно опусти штангу до прямых рук."],"mistakes":["Раскачка корпусом и забрасывание штанги спиной.","Локти уходят вперёд, нагрузка смещается на плечи.","Неполное разгибание рук внизу."],"tip":"Если приходится раскачиваться, сбрось вес: корпус должен оставаться неподвижным.","yt":"8ignu7DXOWw","ych":"Спортивный Бро"},{"id":"Dumbbell_Bicep_Curl","name":"Подъём гантелей на бицепс","group":"Руки","muscles":"Бицепс, плечевая мышца, предплечья","equip":"Гантели","level":"новичок","sets":3,"lo":10,"hi":15,"step":1,"unit":"кг в руке","how":["Встань прямо с гантелями в опущенных руках, локти прижми к бокам.","Разверни ладони вперёд.","Согни руки и подними гантели к плечам, не сдвигая локти.","Наверху на мгновение сожми бицепс.","Медленно опусти гантели до полного выпрямления рук."],"mistakes":["Раскачка корпусом и рывки.","Локти уходят вперёд или в стороны.","Гантели падают вниз без контроля."],"tip":"Опускай гантели в два раза медленнее, чем поднимаешь.","yt":"H_JMAU1NKB8","ych":"Олександр Попенко"},{"id":"Hammer_Curls","name":"Молотковые сгибания","group":"Руки","muscles":"Бицепс, плечевая мышца, плечелучевая мышца","equip":"Гантели","level":"новичок","sets":3,"lo":10,"hi":15,"step":1,"unit":"кг в руке","how":["Встань прямо, гантели в опущенных руках, ладони смотрят друг на друга.","Прижми локти к корпусу.","Согни руки и подними гантели к плечам, не разворачивая кисти.","Задержись наверху и плавно опусти гантели вниз."],"mistakes":["Раскачка корпусом для подъёма веса.","Локти отходят от корпуса вперёд.","Кисти поворачиваются, и хват перестаёт быть нейтральным."],"tip":"Держи гантели как молоток: ладони смотрят друг на друга на всём пути.","yt":"Pd4WUV-boGA","ych":"ТВОЙ ТРЕНЕР: энциклопедия фитнеса"},{"id":"Machine_Preacher_Curls","name":"Бицепс в тренажёре Скотта","group":"Руки","muscles":"Бицепс, плечевая мышца","equip":"Тренажёр","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Отрегулируй сиденье так, чтобы подмышки лежали на верхнем краю подушки.","Положи плечи на подушку и возьмись за рукояти хватом снизу.","Согни руки, поднимая рукояти, локти не отрывай от подушки.","Наверху сожми бицепс и медленно опусти до почти прямых рук."],"mistakes":["Локти отрываются от подушки.","Бросаешь вес вниз и рывком выпрямляешь руки.","Привстаёшь с сиденья, помогая себе корпусом."],"tip":"Внизу не расслабляй руки полностью, чтобы локти не принимали вес на себя.","yt":"xnx8tkx1dUc","ych":"Фитнес простыми словами. Дима Морган"},{"id":"Standing_Biceps_Cable_Curl","name":"Сгибания на бицепс на нижнем блоке","group":"Руки","muscles":"Бицепс, плечевая мышца, предплечья","equip":"Блок","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Встань лицом к нижнему блоку и возьми прямую рукоять хватом снизу на ширине плеч.","Отойди на полшага, локти прижми к корпусу.","Согни руки и подними рукоять к плечам, локти неподвижны.","Наверху сожми бицепс и плавно опусти рукоять до прямых рук."],"mistakes":["Отклоняешься назад и раскачиваешь корпус.","Локти уходят вперёд в верхней точке.","Груз ложится на стопку между повторами, и напряжение пропадает."],"tip":"Блок держит нагрузку на всём пути, поэтому двигайся медленно и без пауз внизу.","yt":"eoqebUqFhMc","ych":"Кузница Спорта"},{"id":"Plank","name":"Планка","group":"Кор","muscles":"Прямая мышца живота, поперечная мышца живота, косые, ягодицы","equip":"Свой вес","level":"новичок","sets":3,"lo":30,"hi":60,"step":0,"unit":"секунды","how":["Встань в упор на предплечья и носки, локти точно под плечами.","Вытяни тело в прямую линию от головы до пяток.","Слегка подкрути таз, напряги пресс и ягодицы.","Дыши ровно и держи положение заданное время."],"mistakes":["Поясница прогибается, живот провисает к полу.","Таз задран вверх, тело складывается домиком.","Задержка дыхания."],"tip":"Не прогибай поясницу: лучше держать меньше секунд, но с ровной спиной.","yt":"bEyqaiGDaIQ","ych":"BodySportal.com"},{"id":"Side_Bridge","name":"Боковая планка","group":"Кор","muscles":"Косые мышцы живота, поперечная мышца живота, средние ягодичные, плечи","equip":"Свой вес","level":"новичок","sets":3,"lo":20,"hi":45,"step":0,"unit":"секунды","how":["Ляг на бок, поставь локоть точно под плечо, ноги выпрями и сложи вместе.","Подними таз, чтобы тело вытянулось в прямую линию от головы до стоп.","Напряги пресс и ягодицы, не давай тазу провисать или уходить назад.","Держи положение заданное время, затем повтори на другом боку."],"mistakes":["Таз проваливается вниз к полу.","Корпус заваливается вперёд или назад.","Плечо уходит к уху, локоть стоит не под плечом."],"tip":"Держи бёдра и плечи в одной плоскости, а поясницу нейтральной, без прогиба.","yt":"LU0dH_L46LI","ych":"Максим Шутко"},{"id":"Dead_Bug","name":"Мёртвый жук","group":"Кор","muscles":"Поперечная мышца живота, прямая мышца живота, косые","equip":"Свой вес","level":"новичок","sets":3,"lo":8,"hi":12,"step":2.5,"unit":"свой вес + кг","how":["Ляг на спину, подними прямые руки вверх, бёдра и колени согни под 90 градусов.","Выдохни и прижми поясницу к полу, держи её так весь подход.","Медленно опусти противоположные руку и ногу почти до пола, выпрямляя ногу.","Верни их в исходное положение и повтори на другую сторону.","Считай повторы на каждую сторону."],"mistakes":["Поясница отрывается от пола и прогибается.","Слишком быстрые движения без контроля.","Задержка дыхания вместо спокойного выдоха."],"tip":"Опускай ногу только до точки, где поясница ещё прижата к полу.","yt":"bsNm4Q0HUhY","ych":"РБК Здоровье"},{"id":"Reverse_Crunch","name":"Обратные скручивания","group":"Кор","muscles":"Прямая мышца живота, косые, сгибатели бедра","equip":"Свой вес","level":"новичок","sets":3,"lo":10,"hi":15,"step":2.5,"unit":"свой вес + кг","how":["Ляг на спину, руки положи вдоль тела ладонями в пол.","Подними ноги: бёдра вертикально, колени согнуты под прямым углом.","На выдохе подкрути таз и оторви его от пола, подтягивая колени к груди.","Медленно опусти таз обратно, не бросая ноги вниз."],"mistakes":["Размахиваешь ногами и поднимаешь таз инерцией.","Отталкиваешься руками от пола.","Поясница прогибается, когда ноги уходят вниз."],"tip":"Движение идёт от таза: скручивай его к рёбрам, а не маши ногами.","yt":"g3HX9ixGKe4","ych":"Михаил Смалько"},{"id":"Hanging_Leg_Raise","name":"Подъём ног в висе","group":"Кор","muscles":"Прямая мышца живота, сгибатели бедра, косые, предплечья","equip":"Свой вес","level":"опытный","sets":3,"lo":8,"hi":12,"step":2.5,"unit":"свой вес + кг","how":["Повисни на перекладине хватом на ширине плеч, ноги прямые, плечи слегка опущены.","Напряги пресс и чуть подкрути таз назад.","Подними ноги до прямого угла с корпусом или выше без рывка.","Медленно опусти ноги, не давая телу раскачиваться."],"mistakes":["Раскачка всем телом и подъём ног за счёт инерции.","Ноги резко падают вниз, тело уходит в маятник.","Таз не подкручивается, работают в основном сгибатели бедра."],"tip":"Если прямые ноги даются тяжело, поднимай согнутые колени, но без раскачки и прогиба в пояснице.","yt":"oWbow6-4XPo","ych":"Кузница Спорта"},{"id":"Cable_Crunch","name":"Скручивания на блоке","group":"Кор","muscles":"Прямая мышца живота, косые","equip":"Блок","level":"новичок","sets":3,"lo":12,"hi":15,"step":2.5,"unit":"кг","how":["Встань на колени лицом к верхнему блоку, возьми канат и прижми руки к голове.","Слегка наклонись вперёд, таз держи над коленями.","На выдохе скрути корпус, направляя локти к середине бёдер.","Задержись внизу и медленно вернись, не давая весу тянуть тебя вверх."],"mistakes":["Садишься тазом на пятки вместо скручивания корпуса.","Тянешь вес руками, а не прессом.","Берёшь слишком большой вес, и работа уходит в поясницу."],"tip":"Таз неподвижен, сгибается только позвоночник: грудь тянется к тазу.","yt":"4dnFqdd61JE","ych":"ТВОЙ ТРЕНЕР: энциклопедия фитнеса"},{"id":"Pallof_Press","name":"Паллоф-пресс (антиротация)","group":"Кор","muscles":"Косые мышцы живота, поперечная мышца живота, прямая мышца живота, ягодицы","equip":"Блок","level":"новичок","sets":3,"lo":10,"hi":12,"step":2.5,"unit":"кг","how":["Поставь рукоять блока на высоту груди и встань к нему боком.","Отойди на шаг, чтобы трос натянулся, ноги на ширине плеч, колени мягкие.","Прижми рукоять к середине груди обеими руками и напряги пресс.","Выжми руки вперёд и удержи 2–3 секунды, не давая корпусу повернуться.","Верни рукоять к груди, а после подхода повернись другим боком."],"mistakes":["Корпус поворачивается к блоку вслед за тросом.","Поясница прогибается, таз уходит вперёд.","Вес слишком большой, удержать его без разворота не получается."],"tip":"Задача упражнения в том, чтобы не дать тросу развернуть тебя: таз и плечи смотрят прямо.","yt":"xZDWuM7PUJQ","ych":"marinaclub1"},{"id":"Farmers_Walk","name":"Прогулка фермера","group":"Кор","muscles":"Предплечья, трапеции, мышцы кора, ягодицы, ноги","equip":"Гантели","level":"новичок","sets":3,"lo":20,"hi":40,"step":2,"unit":"кг в руке","how":["Поставь гантели по бокам от стоп, присядь с ровной спиной и возьми их.","Встань, толкаясь ногами, плечи опусти и слегка отведи назад.","Иди короткими быстрыми шагами, корпус прямой, пресс напряжён.","Считай шаги: один шаг равен одному повтору.","В конце аккуратно поставь гантели, присев с ровной спиной."],"mistakes":["Сутулишься или заваливаешься в сторону под весом.","Плечи поднимаются к ушам, шея зажимается.","Задерживаешь дыхание на всю дистанцию."],"tip":"Поднимай и ставь гантели с ровной спиной, как в становой тяге, а не наклоном.","yt":"_q8Opacf2-4","ych":"Кузница Спорта"},{"id":"Ab_Roller","name":"Ролик для пресса","group":"Кор","muscles":"Прямая мышца живота, поперечная мышца живота, широчайшие, плечи","equip":"Свой вес","level":"опытный","sets":3,"lo":8,"hi":12,"step":2.5,"unit":"свой вес + кг","how":["Встань на колени, поставь ролик на пол под плечами и возьмись за рукояти.","Подкрути таз, напряги пресс и ягодицы.","Медленно кати ролик вперёд, пока удаётся сохранять поясницу ровной.","На выдохе подтяни ролик обратно к коленям силой пресса."],"mistakes":["Поясница прогибается в дальней точке.","Уходишь так далеко, что вернуться без прогиба уже не получается.","Возвращаешься за счёт таза, отводя бёдра назад, а пресс отдыхает."],"tip":"Уходи вперёд только настолько, насколько можешь держать поясницу без прогиба.","yt":"J_bFwCVccGI","ych":"Эльдар Борода!"}];
